head.script:
// 발행기관목록관련

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — listSync 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {

        // 초기화함수

        scwin.init();

        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07243.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출).
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    scwin.bzProcsNo     = $c.data.getParameter("bzProcsNo");
    scwin.listBzDtlTpCd = $c.data.getParameter("listBzDtlTpCd");
    scwin.listInvstgBzTpCd = $c.data.getParameter("listInvstgBzTpCd");

    scwin.clickAdjReqProcsNo = "";
    scwin.clickListBzDtlTpCd = "";
};

