/**
 * @method
 * @name btn_Close_onclick
 * @description 닫기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07243.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name grd_List_oncelldblclick
 * @description 수정승인 ,불가처리
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        scwin.clickListBzDtlTpCd = dlt_modRequestListRes.getCellData(rowIndex, "listBzDtlTpCd");
        scwin.clickAdjReqProcsNo = dlt_modRequestListRes.getCellData(rowIndex,"adjReqProcsNo");

        if(columnId === "confirm") {

            const confirm = await $c.win.confirm('승인처리 하시겠습니까?');
            if (confirm) {
                scwin.submission("35");
            }

        } else if (columnId === "reject") {
            const confirm = await $c.win.confirm('불가처리 하시겠습니까?');

            if (confirm) {
                scwin.submission("36");
            }

        }

    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07243.grd_List_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 목록을 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    // dma_searchReq.set("bzProcsNo",scwin.bzProcsNo) ;//	업무처리번호

    // dma_searchReq.set("listInvstgAttachFileTpCd",scwin.listInvstgAttachFileTpCd);    //상장심사첨부파일구분코드

    dma_searchReq.set("bzProcsNo",scwin.bzProcsNo)
    dma_searchReq.set("listBzDtlTpCd",scwin.listBzDtlTpCd)

    const sbmOptions = {
            id : "sbm_modRequestList",
            action : "/api/listing/lstproc/frgn-com-anl-rpt/modify-request/select-list",
            method : "get",
            ref : "dma_searchReq",
            target : "dlt_modRequestListRes=body",
            isProcessMsg : true
    };

    $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name submission
 * @description 수정 불가 처리
 * @param {String} listProcsStatCd 코드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submission = async function(listProcsStatCd) {

    //  dma_modifyConfirmRejectReq.set("listProcsStatCd",listProcsStatCd); //수정:35, 불가: 36
    //  dma_modifyConfirmRejectReq.set("bzProcsNo",scwin.bzProcsNo); //업무처리번호

    //  dma_modifyConfirmRejectReq.set("listInvstgBzTpCd",scwin.listInvstgBzTpCd); //상장심사업무구분코드
    //  dma_modifyConfirmRejectReq.set("listBzDtlTpCd",scwin.clickListBzDtlTpCd); //	상장업무상세구분코드
    //  dma_modifyConfirmRejectReq.set("adjReqProcsNo", scwin.clickAdjReqProcsNo); //	 수정요청처리번호
    //  dma_modifyConfirmRejectReq.set("regId", $c.session.getUserInfo("empNo")); //	사원번호

    let jsonData = { listProcsStatCd:listProcsStatCd  // 수정:35, 불가: 36
                    , bzProcsNo    : scwin.bzProcsNo  // 업무처리번호
                    , listInvstgBzTpCd :scwin.listInvstgBzTpCd // 상장심사업무구분코드
                    , listBzDtlTpCd :  scwin.clickListBzDtlTpCd //	상장업무상세구분코드
                    , adjReqProcsNo : scwin.clickAdjReqProcsNo  //	 수정요청처리번호
                    , regId : $c.session.getUserInfo("empNo")  //	사원번호
                    };

    const sbmOptions = {
        id : "sbm_modifyConfirmReject",
        action : "/api/listing/lstproc/frgn-com-anl-rpt/modify-request/request",
        method : "post",
        // ref : "dma_modifyConfirmRejectReq",
        // submitDoneHandler : (e) => {
        //     if(e == "success"); {
        //       if( listProcsStatCd == "35") {
        //         $c.win.alert("수정처리 성공했습니다");
        //       } else {
        //         $c.win.alert("불가처리 성공했습니다");
        //       }

        //     }
        // },
        isProcessMsg : true
    };

    const res = await $c.sbm.executeDynamic(sbmOptions,jsonData);
    if(res.responseText = "success") {
        if( listProcsStatCd === "35") {
        await $c.win.alert("수정처리 성공했습니다");
        } else {
        await $c.win.alert("불가처리 성공했습니다");
        }
        await $c.win.closePopup(res.responseText);
    }

};
